    #[test]
    fn modrinth_archive_plan_reads_index_and_extracts_overrides() {
        let root = tempfile::tempdir().expect("tempdir should be available");
        let archive_path = root.path().join("MoreModVariants.mrpack");
        let data_dir = root.path().join("data");
        let directories = LauncherDirectories {
            data_dir: display_path(&data_dir),
            config_dir: display_path(&root.path().join("config")),
            cache_dir: display_path(&root.path().join("cache")),
            log_dir: display_path(&root.path().join("logs")),
        };
        let modrinth_index = br#"{
          "formatVersion": 1,
          "game": "minecraft",
          "versionId": "modrinth-version-7",
          "name": "More Mod Variants",
          "summary": "Fixture pack",
          "files": [
            {
              "path": "mods/sodium-fabric.jar",
              "hashes": {
                "sha1": "0123456789abcdef0123456789abcdef01234567",
                "sha512": "abcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcdefabcd"
              },
              "env": { "client": "required", "server": "unsupported" },
              "downloads": ["https://cdn.modrinth.com/data/example/versions/version/sodium-fabric.jar"],
              "fileSize": 12345
            },
            {
              "path": "mods/server-only.jar",
              "hashes": { "sha1": "1111111111111111111111111111111111111111" },
              "env": { "client": "unsupported", "server": "required" },
              "downloads": ["https://cdn.modrinth.com/data/example/versions/version/server-only.jar"],
              "fileSize": 10
            },
            {
              "path": "mods/optional.jar",
              "hashes": { "sha1": "2222222222222222222222222222222222222222" },
              "env": { "client": "optional", "server": "optional" },
              "downloads": ["https://cdn.modrinth.com/data/example/versions/version/optional.jar"],
              "fileSize": 10
            }
          ],
          "dependencies": {
            "minecraft": "1.20.1",
            "fabric-loader": "0.15.11"
          }
        }"#;
        write_zip_archive(
            &archive_path,
            &[
                ("modrinth.index.json", modrinth_index),
                ("overrides/config/example.toml", b"enabled=true"),
                ("client-overrides/options.txt", b"autoJump:false"),
                ("server-overrides/server.properties", b"motd=skip"),
            ],
        );

        assert!(modpack_archive_contains_modrinth_index(&archive_path)
            .expect("archive should be readable"));
        let plan = build_modrinth_modpack_archive_install_plan(&archive_path, None, &directories)
            .expect("modrinth archive should plan");

        assert_eq!(plan.profile.id, "more-mod-variants");
        assert_eq!(plan.profile.loader, ModLoader::Fabric);
        assert_eq!(plan.profile.game_version, "1.20.1");
        assert_eq!(
            plan.profile.installed_pack_version.as_deref(),
            Some("modrinth-version-7")
        );
        assert_eq!(plan.loader_version.as_deref(), Some("0.15.11"));
        assert_eq!(plan.file_download_plan.items.len(), 1);
        assert_eq!(
            plan.file_download_plan.items[0].url,
            "https://cdn.modrinth.com/data/example/versions/version/sodium-fabric.jar"
        );
        assert_eq!(
            plan.file_download_plan.items[0].sha1.as_deref(),
            Some("0123456789abcdef0123456789abcdef01234567")
        );
        assert_eq!(plan.file_download_plan.items[0].size, Some(12345));
        assert!(plan.file_download_plan.items[0]
            .destination
            .ends_with("profiles/more-mod-variants/mods/sodium-fabric.jar"));

        extract_modrinth_modpack_archive(&archive_path, &plan, &directories)
            .expect("overrides should extract");

        assert_eq!(
            fs::read_to_string(data_dir.join("profiles/more-mod-variants/config/example.toml"))
                .expect("override should write"),
            "enabled=true"
        );
        assert_eq!(
            fs::read_to_string(data_dir.join("profiles/more-mod-variants/options.txt"))
                .expect("client override should write"),
            "autoJump:false"
        );
        assert!(!data_dir
            .join("profiles/more-mod-variants/server.properties")
            .exists());
        assert!(data_dir
            .join("profiles/more-mod-variants/.theboys/modrinth/modrinth.index.json")
            .is_file());
    }

    #[test]
    fn curseforge_archive_extract_rejects_escaping_overrides() {
        let root = tempfile::tempdir().expect("tempdir should be available");
        let archive_path = root.path().join("BadPack.zip");
        let directories = LauncherDirectories {
            data_dir: display_path(&root.path().join("data")),
            config_dir: display_path(&root.path().join("config")),
            cache_dir: display_path(&root.path().join("cache")),
            log_dir: display_path(&root.path().join("logs")),
        };
        let manifest = br#"{
          "name": "BadPack",
          "minecraft": { "version": "1.20.1", "modLoaders": [] },
          "manifestVersion": 1,
          "manifestType": "minecraftModpack",
          "files": [],
          "overrides": "overrides"
        }"#;
        write_zip_archive(
            &archive_path,
            &[
                ("manifest.json", manifest),
                ("overrides/../escape.txt", b"nope"),
            ],
        );
        let plan = build_curseforge_modpack_archive_install_plan(&archive_path, None, &directories)
            .expect("manifest should plan");

        let error = extract_curseforge_modpack_archive(&archive_path, &plan, &directories)
            .expect_err("escaping override should be rejected");

        assert!(error
            .to_string()
            .contains("CurseForge override path must be a safe relative path"));
    }

    #[test]
    fn scanner_detects_supported_launcher_roots() {
        let root = tempfile::tempdir().expect("tempdir should be available");
        let prism = root.path().join("PrismLauncher/instances/WinterPack");
        let multimc = root.path().join("MultiMC/instances/Creative Night");
        let gdlauncher = root.path().join("GDLauncher_next/instances/Sky Lab");
        let atlauncher = root.path().join("ATLauncher/instances/Quest Pack");
        let ftb_app = root.path().join(".ftba/instances/Direwolf20");
        let minecraft = root.path().join(".minecraft");

        fs::create_dir_all(&prism).expect("create prism fixture");
        fs::create_dir_all(&multimc).expect("create multimc fixture");
        fs::create_dir_all(&gdlauncher).expect("create gdlauncher fixture");
        fs::create_dir_all(&atlauncher).expect("create atlauncher fixture");
        fs::create_dir_all(&ftb_app).expect("create ftb app fixture");
        fs::create_dir_all(&minecraft).expect("create minecraft fixture");
        fs::create_dir_all(prism.join("saves/world")).expect("create prism save fixture");
        fs::write(prism.join("saves/world/level.dat"), "level").expect("write prism save");
        fs::write(prism.join("options.txt"), "fov:0.5").expect("write prism options");
        fs::create_dir_all(ftb_app.join(".minecraft/config")).expect("create ftb config fixture");
        fs::write(ftb_app.join(".minecraft/config/ftbquests.snbt"), "quest")
            .expect("write ftb config");
        fs::write(prism.join("theboys-icon.png"), "png").expect("write prism icon");
        fs::create_dir_all(multimc.join("mods")).expect("create multimc mods fixture");
        fs::write(multimc.join("mods/example.jar"), "mod").expect("write multimc mod");
        fs::write(multimc.join("logo.png"), "png").expect("write multimc icon");
        fs::write(
            prism.join("instance.cfg"),
            "name=WinterPack\nnotes=Cozy import fixture\niconKey=theboys-icon",
        )
        .expect("write prism marker");
        fs::write(
            multimc.join("mmc-pack.json"),
            r#"{
              "components": [
                { "uid": "net.minecraft", "version": "1.20.1" },
                { "uid": "net.fabricmc.fabric-loader", "version": "0.15.11" }
              ]
            }"#,
        )
        .expect("write multimc marker");
        fs::write(
            multimc.join("manifest.json"),
            r#"{
              "name": "Creative Night",
              "description": "Shared creative world import",
              "icon": "logo.png"
            }"#,
        )
        .expect("write multimc identity metadata");
        fs::write(
            gdlauncher.join("manifest.json"),
            r#"{
              "name": "Sky Lab",
              "description": "GDLauncher lab fixture",
              "minecraft": {
                "version": "1.19.4",
                "modLoaders": [
                  { "id": "forge-45.4.0", "primary": false },
                  { "id": "quilt-0.21.2", "primary": true }
                ]
              }
            }"#,
        )
        .expect("write gdlauncher metadata");
        fs::write(
            atlauncher.join("minecraftinstance.json"),
            r#"{
              "name": "Quest Pack",
              "summary": "ATLauncher quest fixture",
              "modLoader": "forge",
              "gameVersion": "1.18.2"
            }"#,
        )
        .expect("write atlauncher metadata");
        fs::write(
            ftb_app.join("instance.json"),
            r#"{
              "instanceName": "FTB Presents Direwolf20 1.21",
              "synopsis": "FTB App kitchen-sink fixture",
              "modLoaderType": "neoforge",
              "mcVersion": "1.21.1"
            }"#,
        )
        .expect("write ftb app metadata");
        fs::write(
            minecraft.join("launcher_profiles.json"),
            r#"{
              "selectedProfile": "snapshot-night",
              "profiles": {
                "release": {
                  "name": "Latest Release",
                  "lastVersionId": "1.21.8"
                },
                "snapshot-night": {
                  "name": "Snapshot Night",
                  "lastVersionId": "25w31a"
                }
              }
            }"#,
        )
        .expect("write minecraft marker");

        let candidates =
            scan_imports_in_roots([root.path().to_path_buf()]).expect("scan should pass");

        assert_eq!(candidates.len(), 6);
        assert!(candidates
            .iter()
            .any(|candidate| candidate.kind == ImportKind::Prism
                && candidate.name == "WinterPack"
                && candidate.detected_name.as_deref() == Some("WinterPack")
                && candidate.detected_summary.as_deref() == Some("Cozy import fixture")
                && candidate
                    .detected_icon_path
                    .as_deref()
                    .is_some_and(|path| path.ends_with("/theboys-icon.png"))
                && candidate.importable_file_count == Some(2)
                && candidate.importable_total_bytes == Some(12)
                && candidate.last_modified_unix_seconds.is_some()));
        assert!(candidates
            .iter()
            .any(|candidate| candidate.kind == ImportKind::Multimc
                && candidate.name == "Creative Night"
                && candidate.detected_loader == Some(ModLoader::Fabric)
                && candidate.detected_game_version.as_deref() == Some("1.20.1")
                && candidate.detected_name.as_deref() == Some("Creative Night")
                && candidate.detected_summary.as_deref() == Some("Shared creative world import")
                && candidate
                    .detected_icon_path
                    .as_deref()
                    .is_some_and(|path| path.ends_with("/logo.png"))
                && candidate.importable_file_count == Some(1)
                && candidate.importable_total_bytes == Some(3)));
        assert!(candidates
            .iter()
            .any(|candidate| candidate.kind == ImportKind::Gdlauncher
                && candidate.name == "Sky Lab"
                && candidate.detected_loader == Some(ModLoader::Quilt)
                && candidate.detected_game_version.as_deref() == Some("1.19.4")
                && candidate.detected_summary.as_deref() == Some("GDLauncher lab fixture")));
        assert!(candidates
            .iter()
            .any(|candidate| candidate.kind == ImportKind::Atlauncher
                && candidate.name == "Quest Pack"
                && candidate.detected_loader == Some(ModLoader::Forge)
                && candidate.detected_game_version.as_deref() == Some("1.18.2")
                && candidate.detected_summary.as_deref() == Some("ATLauncher quest fixture")));
        assert!(candidates
            .iter()
            .any(|candidate| candidate.kind == ImportKind::FtbApp
                && candidate.source == "FTB App"
                && candidate.name == "Direwolf20"
                && candidate.detected_loader == Some(ModLoader::Neoforge)
                && candidate.detected_game_version.as_deref() == Some("1.21.1")
                && candidate.detected_name.as_deref() == Some("FTB Presents Direwolf20 1.21")
                && candidate.detected_summary.as_deref() == Some("FTB App kitchen-sink fixture")
                && candidate.importable_file_count == Some(1)
                && candidate.importable_total_bytes == Some(5)));
        assert!(candidates
            .iter()
            .any(|candidate| candidate.kind == ImportKind::Minecraft
                && candidate.detected_loader == Some(ModLoader::Vanilla)
                && candidate.detected_name.as_deref() == Some("Snapshot Night")
                && candidate.detected_game_version.as_deref() == Some("25w31a")
                && candidate.detected_summary.as_deref() == Some("2 launcher profiles detected")
                && candidate.importable_file_count == Some(0)
                && candidate.importable_total_bytes == Some(0)));
    }

